    "w2_home_v2_hero_body": "\u94B1\u5305\u3001\u4EA4\u6613\u6240\u8D26\u6237\u548C\u5B83\u4EEC\u7684\u6062\u590D\u65B9\u6CD5\uFF0C\u5F80\u5F80\u53EA\u6709\u4F60\u81EA\u5DF1\u77E5\u9053\u3002LEGAVIK \u5E2E\u4F60\u628A\u8FD9\u4E9B\u6574\u7406\u6210\u4E00\u4EFD\u52A0\u5BC6\u7684 Recovery Map\u3002\u9700\u8981\u7684\u90A3\u4E00\u5929\uFF0C\u4F60\u6216\u4F60\u4FE1\u4EFB\u7684\u5BB6\u4EBA\u53EF\u4EE5\u7167\u7740\u5B83\u4E86\u89E3\u8D44\u4EA7\u5728\u54EA\u91CC\u3001\u6062\u590D\u9700\u8981\u600E\u4E48\u505A\u3002",
    "w2_home_v2_steps_subtitle": "\u5B58\u4E0B\u6765\u53EA\u662F\u7B2C\u4E00\u6B65\u3002\u5E2E\u52A9\u5BB6\u4EBA\u5230\u65F6\u5019\u627E\u5230\u6062\u590D\u8BF4\u660E\u3001\u770B\u61C2\u6B65\u9AA4\uFF0C\u77E5\u9053\u5982\u4F55\u5F00\u59CB\u3002",
    "w2_home_v2_faq_1_a": "\u5355\u7EAF\u5B58\u6587\u4EF6\uFF0C\u672A\u5FC5\u80FD\u8BA9\u5BB6\u4EBA\u77E5\u9053\u5728\u54EA\u91CC\u3001\u5982\u4F55\u5F00\u59CB\u6062\u590D\u3002",
    "w2_home_v2_security_title_b": "\u7531\u4F60\u638C\u63E1\u6253\u5F00\u5B83\u7684\u6761\u4EF6\u3002",
    "w2_home_v2_step_3_body": "\u5B8C\u6210\u540E\uFF0C\u4F60\u4F1A\u4E0B\u8F7D\u5230\u6062\u590D\u94A5\u5319\uFF08Recovery Kit\uFF09\u548C\u5B58\u50A8\u51ED\u8BC1\uFF08Storage Receipt\uFF09\u3002\u9700\u8981\u7684\u65F6\u5019\uFF0C\u540C\u4E00\u7248\u672C\u7684\u6062\u590D\u94A5\u5319\uFF08Recovery Kit\uFF09\u3001\u5B58\u50A8\u51ED\u8BC1\uFF08Storage Receipt\uFF09\u548C\u6062\u590D\u5BC6\u7801\uFF08Recovery Password\uFF09\u7528\u4E8E\u6062\u590D\u8FD9\u4EFD Map\u3002\u4F60\u53EF\u4EE5\u63D0\u524D\u544A\u8BC9\u5BB6\u4EBA\u5B83\u4EEC\u653E\u5728\u54EA\u91CC\u3002",
    "w2_home_v2_trust_3_body": "\u6587\u4EF6\u5B58\u5728\u53BB\u4E2D\u5FC3\u5316\u7F51\u7EDC\u4E0A\uFF0C\u4E0D\u5728\u6211\u4EEC\u7684\u670D\u52A1\u5668\u91CC\uFF0C\u6062\u590D\u4E5F\u4E0D\u4F9D\u8D56\u6211\u4EEC\u7684\u7F51\u7AD9\u3002\u4FDD\u5B58\u597D\u540C\u4E00\u7248\u672C\u7684\u6062\u590D\u94A5\u5319\uFF08Recovery Kit\uFF09\u3001\u5B58\u50A8\u51ED\u8BC1\uFF08Storage Receipt\uFF09\u548C\u6062\u590D\u5BC6\u7801\uFF08Recovery Password\uFF09\uFF0C\u7528\u4E8E\u901A\u8FC7\u72EC\u7ACB\u6062\u590D\u5DE5\u5177\u6062\u590D\u8FD9\u4EFD Map\u3002",
    "w2_home_v2_faq_cloud_detail": "\u7F51\u76D8\u91CC\u7684\u6587\u4EF6\uFF0C\u5E73\u53F0\u901A\u5E38\u80FD\u63A5\u89E6\u5230\u539F\u6587\uFF1B\u5BB6\u4EBA\u8981\u6253\u5F00\uFF0C\u8FD8\u5F97\u5148\u767B\u5F55\u4F60\u7684\u8D26\u6237\u3001\u8FC7\u4F60\u7684\u4E24\u6B65\u9A8C\u8BC1\uFF0C\u800C\u8FD9\u6070\u6070\u662F\u4ED6\u4EEC\u6700\u53EF\u80FD\u5361\u4F4F\u7684\u5730\u65B9\uFF1B\u8D26\u6237\u4E00\u65E6\u88AB\u505C\u7528\u6216\u957F\u671F\u4E0D\u767B\u5F55\uFF0C\u6587\u4EF6\u4E5F\u53EF\u80FD\u8DDF\u7740\u6CA1\u4E86\u3002LEGAVIK \u7684 Map \u5148\u5728\u4F60\u7684\u6D4F\u89C8\u5668\u91CC\u52A0\u5BC6\uFF0C\u518D\u5B58\u5230\u53BB\u4E2D\u5FC3\u5316\u5B58\u50A8\u7F51\u7EDC\u4E0A\uFF0C\u7531\u5168\u7403\u8BB8\u591A\u8282\u70B9\u5171\u540C\u4FDD\u5B58\uFF0C\u4E0D\u5F52\u4EFB\u4F55\u4E00\u5BB6\u516C\u53F8\uFF08\u5305\u62EC\u6211\u4EEC\uFF09\u5355\u72EC\u63A7\u5236\uFF0C\u4E0A\u4F20\u540E\u4E5F\u4E0D\u80FD\u88AB\u6539\u52A8\u3002\u6253\u5F00\u5B83\u4E0D\u9700\u8981\u767B\u5F55\u4EFB\u4F55\u4EBA\u7684\u8D26\u6237\uFF0C\u540C\u4E00\u7248\u672C\u7684\u6062\u590D\u94A5\u5319\uFF08Recovery Kit\uFF09\u3001\u5B58\u50A8\u51ED\u8BC1\uFF08Storage Receipt\uFF09\u548C\u6062\u590D\u5BC6\u7801\uFF08Recovery Password\uFF09\u7528\u4E8E\u6062\u590D\u8FD9\u4EFD Map\uFF1B\u800C\u4E14\u6309\u516D\u4E2A\u90E8\u5206\u5F15\u5BFC\u4F60\u6574\u7406\uFF0C\u5E2E\u52A9\u51CF\u5C11\u5173\u952E\u9057\u6F0F\u3002",
    "w2_home_v2_faq_3_a": "\u4FDD\u5B58\u597D\u540C\u4E00\u7248\u672C\u7684\u6062\u590D\u94A5\u5319\uFF08Recovery Kit\uFF09\u3001\u5B58\u50A8\u51ED\u8BC1\uFF08Storage Receipt\uFF09\u548C\u6062\u590D\u5BC6\u7801\uFF08Recovery Password\uFF09\uFF0C\u7528\u4E8E\u901A\u8FC7\u72EC\u7ACB\u6062\u590D\u5DE5\u5177\u6062\u590D\u8FD9\u4EFD Map\uFF0C\u4E0D\u9700\u8981\u767B\u5F55\u6211\u4EEC\u7684\u7F51\u7AD9\u3002",
    "w2_home_v2_faq_5_a": "\u6253\u5F00\u6062\u590D\u9875\u9762\uFF0C\u51C6\u5907\u597D\u540C\u4E00\u7248\u672C\u7684\u6062\u590D\u94A5\u5319\uFF08Recovery Kit\uFF09\u3001\u5B58\u50A8\u51ED\u8BC1\uFF08Storage Receipt\uFF09\u548C\u6062\u590D\u5BC6\u7801\uFF08Recovery Password\uFF09\uFF0C\u6309\u63D0\u793A\u64CD\u4F5C\uFF0C\u7528\u4E8E\u6062\u590D\u8FD9\u4EFD Map\u3002\u8BF7\u63D0\u524D\u544A\u8BC9\u5BB6\u4EBA\u8FD9\u4E9B\u6062\u590D\u6750\u6599\u653E\u5728\u54EA\u91CC\u3002",
    "w2_home_v2_faq_0_a": "\u90FD\u4E0D\u662F\u3002\u6211\u4EEC\u4E0D\u4FDD\u7BA1\u8D44\u4EA7\uFF0C\u4E5F\u4E0D\u662F\u65E5\u5E38\u7528\u7684\u5BC6\u7801\u5DE5\u5177\u3002LEGAVIK \u53EA\u505A\u4E00\u4EF6\u4E8B\uFF1A\u628A\u6062\u590D\u65B9\u6CD5\u6574\u7406\u597D\u3001\u52A0\u5BC6\u4FDD\u5B58\uFF0C\u4E3A\u9700\u8981\u65F6\u6253\u5F00\u8FD9\u4EFD Map \u505A\u51C6\u5907\u3002",
    "w2_text_413b8b2a72d3": "\u7559\u4E0B\u6E05\u6670\u7684\u6062\u590D\u8BA1\u5212\u4E0E\u8DEF\u5F84\u3002",
    "w2_home_v2_footer_description": "\u4E3A\u4F60\u7684\u6570\u5B57\u8D44\u4EA7\uFF0C\u7559\u4E0B\u6E05\u6670\u7684\u6062\u590D\u8BA1\u5212\u4E0E\u8DEF\u5F84\u3002",
    "w2_text_eba6072fa9bd": "\u5305\u542B\u4E0E\u52A0\u5BC6\u8D44\u4EA7\u6062\u590D\u76F8\u5173\u7684\u5173\u952E\u8D26\u6237\u6062\u590D\u7EBF\u7D22\u6574\u7406",
    "w2_text_2b01f79e0f1f": "\u5305\u542B\u4E0E\u52A0\u5BC6\u8D44\u4EA7\u6062\u590D\u76F8\u5173\u7684\u5173\u952E\u8D26\u6237\u6062\u590D\u7EBF\u7D22\u6574\u7406",
    "w2_text_991afa2c4727": "\u5E2E\u52A9\u4ECA\u5929\u5EFA\u7ACB\u597D\u7684\u6062\u590D\u4F53\u7CFB\uFF0C\u5728\u672A\u6765\u771F\u6B63\u9700\u8981\u4F7F\u7528\u7684\u65F6\u5019\uFF0C\u4FDD\u6301\u6E05\u695A\u3001\u53CA\u65F6\u3001\u53EF\u7528\u3002",
    "w2_text_858c4ecfa113": "\u901A\u8FC7\u5B9A\u671F\u68C0\u67E5\u548C\u66F4\u65B0\uFF0C\u5C3D\u91CF\u4FDD\u6301\u5DF2\u7ECF\u8BBE\u8BA1\u597D\u7684\u4F20\u627F\u5B89\u6392\u4E0E\u60A8\u7684\u771F\u5B9E\u5BB6\u5EAD\u548C\u5B9E\u9645\u60C5\u51B5\u4E00\u81F4\u3002",
    "w2_text_4ef0ae55a5a1": "\u534F\u52A9\u68B3\u7406\u672A\u6765\u4EA4\u63A5\u8BA1\u5212\uFF1B\u5B9E\u9645\u4FDD\u7BA1\u4E0E\u4EA4\u63A5\u7531\u5BA2\u6237\u81EA\u884C\u5B89\u6392",
    "w2_text_6a92e93433b9": "\u534F\u52A9\u68B3\u7406\u672A\u6765\u4EA4\u63A5\u8BA1\u5212\uFF1B\u5B9E\u9645\u4FDD\u7BA1\u4E0E\u4EA4\u63A5\u7531\u5BA2\u6237\u81EA\u884C\u5B89\u6392",
    "w2_text_cfef68e55413": "\u534F\u52A9\u68B3\u7406\u672A\u6765\u4EA4\u63A5\u8BA1\u5212\uFF1B\u5B9E\u9645\u4FDD\u7BA1\u4E0E\u4EA4\u63A5\u7531\u5BA2\u6237\u81EA\u884C\u5B89\u6392",
    "w2_text_99487da6e167": "\u534F\u52A9\u68B3\u7406\u672A\u6765\u4EA4\u63A5\u8BA1\u5212\uFF1B\u5B9E\u9645\u4FDD\u7BA1\u4E0E\u4EA4\u63A5\u7531\u5BA2\u6237\u81EA\u884C\u5B89\u6392",
    "w2_text_37b3be624c4a": "\u534F\u52A9\u68B3\u7406\u672A\u6765\u4EA4\u63A5\u8BA1\u5212\uFF1B\u5B9E\u9645\u4FDD\u7BA1\u4E0E\u4EA4\u63A5\u7531\u5BA2\u6237\u81EA\u884C\u5B89\u6392",
    "w2_text_2347ae4bc684": "\u534F\u52A9\u68B3\u7406\u672A\u6765\u4EA4\u63A5\u8BA1\u5212\uFF1B\u5B9E\u9645\u4FDD\u7BA1\u4E0E\u4EA4\u63A5\u7531\u5BA2\u6237\u81EA\u884C\u5B89\u6392",
    "w2_text_30b24a44ee44": "\u6062\u590D\u6750\u6599\u4FDD\u7BA1\u4E0E\u4EA4\u63A5\u89C4\u5212\uFF08\u89C4\u5212\u4E2D\uFF0C\u5C1A\u672A\u63D0\u4F9B\uFF09",
