    "w2_text_516146072410": "\u534F\u8C03\u4E13\u4E1A\u89D2\u8272\uFF08\u89C4\u5212\u4E2D\uFF0C\u5C1A\u672A\u63D0\u4F9B\uFF09",
    "w2_text_908b43aadabb": "\u5F8B\u5E08\u3001\u53D7\u6258\u4EBA\u3001\u9057\u4EA7\u6267\u884C\u4EBA\u6216\u5176\u4ED6\u4E13\u4E1A\u89D2\u8272\u3002\uFF08\u89C4\u5212\u4E2D\uFF0C\u5C1A\u672A\u63D0\u4F9B\uFF09",
    "w2_text_2fe2e5aed3a4": "\u6839\u636E\u5B9E\u9645\u9700\u8981\uFF0C\u5B89\u6392\u672A\u6765\u4EC0\u4E48\u65F6\u5019\u542F\u52A8\u4EA4\u63A5\uFF0C\u4EE5\u53CA\u4E0D\u540C\u53C2\u4E0E\u4EBA\u5458\u5982\u4F55\u914D\u5408\u3002\uFF08\u89C4\u5212\u4E2D\uFF0C\u5C1A\u672A\u63D0\u4F9B\uFF09",
    "w2_text_8155e513de19": "\u5982\u6709\u9700\u8981\uFF0C\u53EF\u5C06\u5F8B\u5E08\u3001\u53D7\u6258\u4EBA\u3001\u9057\u4EA7\u6267\u884C\u4EBA\u6216\u5176\u4ED6\u4E13\u4E1A\u4EBA\u58EB\u7EB3\u5165\u6574\u4F53\u5B89\u6392\u3002\uFF08\u89C4\u5212\u4E2D\uFF0C\u5C1A\u672A\u63D0\u4F9B\uFF09",
    "w2_text_3a7b07d45df3": "\u6309\u65B9\u6848\uFF08\u89C4\u5212\u4E2D\uFF0C\u5C1A\u672A\u63D0\u4F9B\uFF09",
    "w2_text_e54a8948fa6f": "\u5F53\u7EA6\u5B9A\u6761\u4EF6\u6EE1\u8DB3\u65F6\uFF0C\u6307\u5B9A\u6062\u590D\u4EBA\u53EF\u6309\u5B89\u6392\u5C1D\u8BD5\u53D6\u5F97\u76F8\u5173\u6750\u6599\u5E76\u5F00\u59CB\u6062\u590D\uFF0C\u5B9E\u9645\u53D6\u51B3\u4E8E\u6750\u6599\u3001\u6388\u6743\u548C\u7B2C\u4E09\u65B9\u6761\u4EF6\u3002\uFF08\u89C4\u5212\u4E2D\uFF0C\u5C1A\u672A\u63D0\u4F9B\uFF09",
    "w2_footer_disclaimer": "LEGAVIK \u4E0D\u6301\u6709\u4F60\u7684\u8D44\u4EA7\u3001\u79C1\u94A5\u6216\u52A9\u8BB0\u8BCD\uFF0C\u4E5F\u4E0D\u4FDD\u8BC1\u8D44\u4EA7\u80FD\u591F\u627E\u56DE\u3002",
