    "cc_86d2c690b9a9": "Calculated after update",
    "cc_66f995945001": "View Recovery Review report",
    "cc_7964ab4d296e": "Review again",
    "cc_c71674820946": "Start Recovery Review early",
    "cc_e67bf691bc33": "This is where you manage your LEGAVIK website account. It isn't connected to your Recovery Map's recovery files.",
