    "text_36157b7e074c": "Single Recovery Map update",
    "text_8459aa46b1f9": "Updates the content of a Recovery Map you've already built.",
    "text_329070f0d683": "After payment, you'll start the update from your Customer Centre.",
    "text_428917458bd8": "Confirm your purchase",
    "text_57a871771b81": "You'll be charged in your account's billing currency",
